type PlanScopedUpsertBulk struct {
	b       *PlanScopedCreateBulk
	t       *PlanScoped
	columns []string
	opts    []func(*PlanUpsertBulk)
}

// OnConflictColumns configures the columns as conflict target. A conflicting row of
// another Workspace is never updated.
func (b *PlanScopedCreateBulk) OnConflictColumns(columns ...string) *PlanScopedUpsertBulk {
	return &PlanScopedUpsertBulk{b: b, t: &PlanScoped{s: b.s}, columns: columns}
}

// UpdateNewValues updates the mutable fields using the new values set on create.
func (u *PlanScopedUpsertBulk) UpdateNewValues() *PlanScopedUpsertBulk {
	u.opts = append(u.opts, func(r *PlanUpsertBulk) { r.UpdateNewValues() })
	return u
}

// Ignore sets each column to itself in case of conflict.
func (u *PlanScopedUpsertBulk) Ignore() *PlanScopedUpsertBulk {
	u.opts = append(u.opts, func(r *PlanUpsertBulk) { r.Ignore() })
	return u
}

// DoNothing configures the conflict_action to `DO NOTHING`.
func (u *PlanScopedUpsertBulk) DoNothing() *PlanScopedUpsertBulk {
	u.opts = append(u.opts, func(r *PlanUpsertBulk) { r.DoNothing() })
	return u
}

// Update overrides fields' `UPDATE` values.
func (u *PlanScopedUpsertBulk) Update(set func(*PlanScopedUpsert)) *PlanScopedUpsertBulk {
	u.opts = append(u.opts, func(r *PlanUpsertBulk) {
		r.Update(func(s *PlanUpsert) { set(&PlanScopedUpsert{u: s.UpdateSet}) })
	})
	return u
}

// Exec verifies every builder's references, then executes the upsert.
func (u *PlanScopedUpsertBulk) Exec(ctx context.Context) error {
	if u.b.s.auditing() {
		return ErrAuditUpsert
	}
	raw, err := u.b.raw(ctx)
	if err != nil {
		return err
	}
	r := raw.OnConflict(u.t.conflictOptions(u.columns, nil)...)
	for _, o := range u.opts {
		o(r)
	}
	return r.Exec(ctx)
}

