func (x *PlanScopedUpdateOne) check(ctx context.Context) error {
	m := x.b.Mutation()
	_ = m
	if err := x.s.verifyPlanVersion(ctx, m.VersionsIDs()); err != nil {
		return fmt.Errorf("versions: %w", err)
	}
	if err := x.s.verifyPlanVersion(ctx, m.LiveVersionIDs()); err != nil {
		return fmt.Errorf("live_version: %w", err)
	}
	if err := x.s.verifyPlanVersion(ctx, m.DraftVersionIDs()); err != nil {
		return fmt.Errorf("draft_version: %w", err)
	}
	return nil
}

// Save verifies the references against the Workspace, then updates the Plan.
func (x *PlanScopedUpdateOne) Save(ctx context.Context) (*Plan, error) {
	if err := x.check(ctx); err != nil {
		return nil, err
	}
	if x.s.auditing() {
		var updated *Plan
		err := x.s.audited(ctx, func(ts *Scoped) error {
			id, _ := x.b.Mutation().ID()
			before, err := ts.c.Plan.Query().Where(x.b.mutation.predicates...).Where(plan.ID(id)).Only(ctx)
			if err != nil {
				return err
			}
			x.b.auditRebind(ts.c)
			if updated, err = x.b.Save(ctx); err != nil {
				return err
			}
			return ts.record(ctx, auditChangePlan("update", before, updated))
		})
		return updated, err
	}
	return x.b.Save(ctx)
}

// Exec is like Save, discarding the entity.
func (x *PlanScopedUpdateOne) Exec(ctx context.Context) error {
	_, err := x.Save(ctx)
	return err
}

// PlanScopedUpdate wraps PlanUpdate: a conditional bulk update of one Workspace.
type PlanScopedUpdate struct {
	s *Scoped
	b *PlanUpdate
	// modErr is set when a Modify modifier tried to assign workspace_id.
	modErr error
}

// Update updates the Plan entities of the Workspace that match the predicates.
func (t *PlanScoped) Update() *PlanScopedUpdate {
	return &PlanScopedUpdate{s: t.s, b: t.s.c.Plan.Update().Where(plan.WorkspaceID(t.s.ws))}
}

// Where appends predicates the rows must match.
func (x *PlanScopedUpdate) Where(ps ...predicate.Plan) *PlanScopedUpdate {
	x.b.Where(ps...)
	return x
}

// Modify adds a statement modifier for computed assignments the typed setters cannot
// express (SET col = LEAST(col + ..., ...)). A modifier gets assignment-only access
// (ScopedAssign), so it cannot widen the Workspace predicate; an assignment to
// workspace_id is refused: each modifier is probed against a scratch statement here, and
// Save fails with ErrWorkspaceAssign.
func (x *PlanScopedUpdate) Modify(modifiers ...func(a *ScopedAssign)) *PlanScopedUpdate {
	for _, m := range modifiers {
		probe := &ScopedAssign{u: sql.Update(plan.Table)}
		m(probe)
		if probe.workspace {
			x.modErr = ErrWorkspaceAssign
		}
		x.b.Modify(func(u *sql.UpdateBuilder) { m(&ScopedAssign{u: u}) })
	}
	return x
}

