// PlanVersionScopedCreateBulk creates several PlanVersion entities of one Workspace at once.
type PlanVersionScopedCreateBulk struct {
	s  *Scoped
	xs []*PlanVersionScopedCreate
}

// CreateBulk batches creates started on this Workspace.
func (t *PlanVersionScoped) CreateBulk(xs ...*PlanVersionScopedCreate) *PlanVersionScopedCreateBulk {
	return &PlanVersionScopedCreateBulk{s: t.s, xs: xs}
}

func (b *PlanVersionScopedCreateBulk) raw(ctx context.Context) (*PlanVersionCreateBulk, error) {
	builders := make([]*PlanVersionCreate, len(b.xs))
	for i, x := range b.xs {
		if x.s.ws != b.s.ws {
			return nil, fmt.Errorf("PlanVersion: builder of another scope: %w", ErrNotInWorkspace)
		}
		if err := x.check(ctx); err != nil {
			return nil, err
		}
		builders[i] = x.b
	}
	return b.s.c.PlanVersion.CreateBulk(builders...), nil
}

// Save verifies every builder's references, then creates the PlanVersion entities.
func (b *PlanVersionScopedCreateBulk) Save(ctx context.Context) ([]*PlanVersion, error) {
	raw, err := b.raw(ctx)
	if err != nil {
		return nil, err
	}
	return raw.Save(ctx)
}

// Exec is like Save, discarding the entities.
func (b *PlanVersionScopedCreateBulk) Exec(ctx context.Context) error {
	_, err := b.Save(ctx)
	return err
}

// ---------------------------------------------------------------- upsert

// PlanVersionScopedUpsert is the "ON CONFLICT ... DO UPDATE" setter. It cannot move a row to
// another Workspace or point a reference at a value that was not verified on create.
type PlanVersionScopedUpsert struct{ u *sql.UpdateSet }

// SetUpdatedAt sets the "updated_at" field.
func (u *PlanVersionScopedUpsert) SetUpdatedAt(v time.Time) *PlanVersionScopedUpsert {
	u.u.Set(planversion.FieldUpdatedAt, v)
	return u
}

// UpdateUpdatedAt sets the "updated_at" field to the value that was provided on create.
func (u *PlanVersionScopedUpsert) UpdateUpdatedAt() *PlanVersionScopedUpsert {
	u.u.SetExcluded(planversion.FieldUpdatedAt)
	return u
}

// UpdatePlanID sets the "plan_id" field to the value that was provided on create.
func (u *PlanVersionScopedUpsert) UpdatePlanID() *PlanVersionScopedUpsert {
	u.u.SetExcluded(planversion.FieldPlanID)
	return u
}

// SetBody sets the "body" field.
func (u *PlanVersionScopedUpsert) SetBody(v string) *PlanVersionScopedUpsert {
	u.u.Set(planversion.FieldBody, v)
	return u
}

// UpdateBody sets the "body" field to the value that was provided on create.
func (u *PlanVersionScopedUpsert) UpdateBody() *PlanVersionScopedUpsert {
	u.u.SetExcluded(planversion.FieldBody)
	return u
}

// conflictOptions confines the DO UPDATE part to rows of the Workspace.
// target, when not nil, is the predicate of a partial unique index the conflict is inferred from.
func (t *PlanVersionScoped) conflictOptions(columns []string, target *sql.Predicate) []sql.ConflictOption {
	opts := []sql.ConflictOption{
		sql.ConflictColumns(columns...),
		sql.UpdateWhere(sql.EQ(planversion.FieldWorkspaceID, t.s.ws)),
	}
	if target != nil {
		opts = append(opts, sql.ConflictWhere(target))
	}
	return opts
}

// PlanVersionScopedUpsertOne is the "upsert" of one PlanVersion.
type PlanVersionScopedUpsertOne struct {
	x *PlanVersionScopedCreate
	u *PlanVersionUpsertOne
	// doNothing: the conflict action is DO NOTHING (the only upsert an audited entity allows).
	doNothing bool
}

// OnConflictColumns configures the columns as conflict target. A conflicting row of
// another Workspace is never updated.
func (x *PlanVersionScopedCreate) OnConflictColumns(columns ...string) *PlanVersionScopedUpsertOne {
	return x.OnConflictColumnsWhere(nil, columns...)
}

// OnConflictColumnsWhere is OnConflictColumns for a partial unique index: target is the
// index's predicate, which Postgres needs to infer the index from the columns.
func (x *PlanVersionScopedCreate) OnConflictColumnsWhere(target *sql.Predicate, columns ...string) *PlanVersionScopedUpsertOne {
	return &PlanVersionScopedUpsertOne{x: x, u: x.b.OnConflict((&PlanVersionScoped{s: x.s}).conflictOptions(columns, target)...)}
}

// UpdateNewValues updates the mutable fields using the new values set on create.
func (u *PlanVersionScopedUpsertOne) UpdateNewValues() *PlanVersionScopedUpsertOne {
	u.u.UpdateNewValues()
	return u
}

// Ignore sets each column to itself in case of conflict.
func (u *PlanVersionScopedUpsertOne) Ignore() *PlanVersionScopedUpsertOne {
	u.u.Ignore()
	return u
}

// DoNothing configures the conflict_action to `DO NOTHING`.
func (u *PlanVersionScopedUpsertOne) DoNothing() *PlanVersionScopedUpsertOne {
	u.u.DoNothing()
	u.doNothing = true
	return u
}

// Update overrides fields' `UPDATE` values.
func (u *PlanVersionScopedUpsertOne) Update(set func(*PlanVersionScopedUpsert)) *PlanVersionScopedUpsertOne {
	u.u.Update(func(s *PlanVersionUpsert) { set(&PlanVersionScopedUpsert{u: s.UpdateSet}) })
	return u
}

// Exec verifies the references, then executes the upsert.
func (u *PlanVersionScopedUpsertOne) Exec(ctx context.Context) error {
	if err := u.x.check(ctx); err != nil {
		return err
	}
	return u.u.Exec(ctx)
}

// ID is like Exec, returning the inserted or updated id.
func (u *PlanVersionScopedUpsertOne) ID(ctx context.Context) (int64, error) {
	if err := u.x.check(ctx); err != nil {
		return 0, err
	}
	return u.u.ID(ctx)
}

// PlanVersionScopedUpsertBulk is the "upsert" of several PlanVersion entities.
type PlanVersionScopedUpsertBulk struct {
	b       *PlanVersionScopedCreateBulk
	t       *PlanVersionScoped
	columns []string
	opts    []func(*PlanVersionUpsertBulk)
}

// OnConflictColumns configures the columns as conflict target. A conflicting row of
// another Workspace is never updated.
func (b *PlanVersionScopedCreateBulk) OnConflictColumns(columns ...string) *PlanVersionScopedUpsertBulk {
	return &PlanVersionScopedUpsertBulk{b: b, t: &PlanVersionScoped{s: b.s}, columns: columns}
}

// UpdateNewValues updates the mutable fields using the new values set on create.
func (u *PlanVersionScopedUpsertBulk) UpdateNewValues() *PlanVersionScopedUpsertBulk {
	u.opts = append(u.opts, func(r *PlanVersionUpsertBulk) { r.UpdateNewValues() })
	return u
}

// Ignore sets each column to itself in case of conflict.
func (u *PlanVersionScopedUpsertBulk) Ignore() *PlanVersionScopedUpsertBulk {
	u.opts = append(u.opts, func(r *PlanVersionUpsertBulk) { r.Ignore() })
	return u
}

// DoNothing configures the conflict_action to `DO NOTHING`.
func (u *PlanVersionScopedUpsertBulk) DoNothing() *PlanVersionScopedUpsertBulk {
	u.opts = append(u.opts, func(r *PlanVersionUpsertBulk) { r.DoNothing() })
	return u
}

// Update overrides fields' `UPDATE` values.
func (u *PlanVersionScopedUpsertBulk) Update(set func(*PlanVersionScopedUpsert)) *PlanVersionScopedUpsertBulk {
	u.opts = append(u.opts, func(r *PlanVersionUpsertBulk) {
		r.Update(func(s *PlanVersionUpsert) { set(&PlanVersionScopedUpsert{u: s.UpdateSet}) })
	})
	return u
}

// Exec verifies every builder's references, then executes the upsert.
func (u *PlanVersionScopedUpsertBulk) Exec(ctx context.Context) error {
	raw, err := u.b.raw(ctx)
	if err != nil {
		return err
	}
	r := raw.OnConflict(u.t.conflictOptions(u.columns, nil)...)
	for _, o := range u.opts {
		o(r)
	}
	return r.Exec(ctx)
}

