// PlanVersionScopedUpdate wraps PlanVersionUpdate: a conditional bulk update of one Workspace.
type PlanVersionScopedUpdate struct {
	s *Scoped
	b *PlanVersionUpdate
	// modErr is set when a Modify modifier tried to assign workspace_id.
	modErr error
}

// Update updates the PlanVersion entities of the Workspace that match the predicates.
func (t *PlanVersionScoped) Update() *PlanVersionScopedUpdate {
	return &PlanVersionScopedUpdate{s: t.s, b: t.s.c.PlanVersion.Update().Where(planversion.WorkspaceID(t.s.ws))}
}

// Where appends predicates the rows must match.
func (x *PlanVersionScopedUpdate) Where(ps ...predicate.PlanVersion) *PlanVersionScopedUpdate {
	x.b.Where(ps...)
	return x
}

// Modify adds a statement modifier for computed assignments the typed setters cannot
// express (SET col = LEAST(col + ..., ...)). A modifier gets assignment-only access
// (ScopedAssign), so it cannot widen the Workspace predicate; an assignment to
// workspace_id is refused: each modifier is probed against a scratch statement here, and
// Save fails with ErrWorkspaceAssign.
func (x *PlanVersionScopedUpdate) Modify(modifiers ...func(a *ScopedAssign)) *PlanVersionScopedUpdate {
	for _, m := range modifiers {
		probe := &ScopedAssign{u: sql.Update(planversion.Table)}
		m(probe)
		if probe.workspace {
			x.modErr = ErrWorkspaceAssign
		}
		x.b.Modify(func(u *sql.UpdateBuilder) { m(&ScopedAssign{u: u}) })
	}
	return x
}

// SetUpdatedAt sets the "updated_at" field.
func (x *PlanVersionScopedUpdate) SetUpdatedAt(v time.Time) *PlanVersionScopedUpdate {
	x.b.SetUpdatedAt(v)
	return x
}

// SetPlanID sets the "plan_id" field.
func (x *PlanVersionScopedUpdate) SetPlanID(v int64) *PlanVersionScopedUpdate {
	x.b.SetPlanID(v)
	return x
}

// SetNillablePlanID sets the "plan_id" field if the given value is not nil.
func (x *PlanVersionScopedUpdate) SetNillablePlanID(v *int64) *PlanVersionScopedUpdate {
	x.b.SetNillablePlanID(v)
	return x
}

// SetBody sets the "body" field.
func (x *PlanVersionScopedUpdate) SetBody(v string) *PlanVersionScopedUpdate {
	x.b.SetBody(v)
	return x
}

// SetNillableBody sets the "body" field if the given value is not nil.
func (x *PlanVersionScopedUpdate) SetNillableBody(v *string) *PlanVersionScopedUpdate {
	x.b.SetNillableBody(v)
	return x
}

// SetPlan sets the "plan" edge to the Plan entity.
func (x *PlanVersionScopedUpdate) SetPlan(v *Plan) *PlanVersionScopedUpdate {
	x.b.SetPlan(v)
	return x
}

// ClearPlan clears the "plan" edge to the Plan entity.
func (x *PlanVersionScopedUpdate) ClearPlan() *PlanVersionScopedUpdate {
	x.b.ClearPlan()
	return x
}

func (x *PlanVersionScopedUpdate) check(ctx context.Context) error {
	m := x.b.Mutation()
	_ = m
	if err := x.s.verifyPlan(ctx, m.PlanIDs()); err != nil {
		return fmt.Errorf("plan: %w", err)
	}
	return nil
}

// Save verifies the references against the Workspace, then updates the rows and
// returns how many changed.
func (x *PlanVersionScopedUpdate) Save(ctx context.Context) (int, error) {
	if x.modErr != nil {
		return 0, x.modErr
	}
	if err := x.check(ctx); err != nil {
		return 0, err
	}
	return x.b.Save(ctx)
}

// Exec is like Save, discarding the count.
func (x *PlanVersionScopedUpdate) Exec(ctx context.Context) error {
	_, err := x.Save(ctx)
	return err
}
